<script lang="ts">
 import{memorialContour,memorialShapes,sampleRing,type MemorialShape}from'@schubert/geometry';
 let{value=$bindable('rectangle'),onchange=()=>{}}:{value?:MemorialShape;onchange?:(shape:MemorialShape)=>void}=$props();
 function path(shape:MemorialShape){const points=sampleRing(memorialContour(shape,'100',shape==='circle'?'100':'140').outer);return points.map((p,i)=>`${i?'L':'M'}${Number(p.xMm)+10} ${150-Number(p.yMm)}`).join(' ')+'Z';}
</script>
<div class="shape-picker" role="group" aria-label="Grundform auswählen">{#each memorialShapes as shape}<button type="button" class:chosen={value===shape.id} aria-pressed={value===shape.id} onclick={()=>{value=shape.id;onchange(shape.id);}}><svg viewBox="0 0 120 160" aria-hidden="true"><path d={path(shape.id)}/></svg><span>{shape.label}</span></button>{/each}</div>
<style>.shape-picker{display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:8px;margin:12px 0 20px}.shape-picker button{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:8px;min-height:114px;padding:12px 7px;border:1px solid var(--line);border-radius:10px;background:var(--paper);color:var(--ink);font:inherit;font-size:12px;line-height:1.35;cursor:pointer}.shape-picker svg{height:62px;width:52px;flex:none;overflow:visible}.shape-picker path{fill:var(--wash);stroke:var(--muted);stroke-width:2}.shape-picker button:hover{background:var(--wash)}.shape-picker button.chosen{border-color:var(--forest);background:var(--accent-wash)}.shape-picker button.chosen path{stroke:var(--forest);fill:color-mix(in srgb,var(--forest) 15%,var(--paper))}.shape-picker button:focus-visible{outline:2px solid var(--forest);outline-offset:2px}@media(max-width:600px){.shape-picker{grid-template-columns:repeat(3,minmax(0,1fr))}.shape-picker button{font-size:12px}}</style>
